USE sentinel_ai_security;
CREATE TABLE IF NOT EXISTS inspections (
    inspection_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, inspection_uuid CHAR(36) NOT NULL, company_id BIGINT UNSIGNED NOT NULL, site_id BIGINT UNSIGNED NOT NULL, inspector_employee_id BIGINT UNSIGNED NULL, inspector_user_id BIGINT UNSIGNED NULL,
    inspection_type VARCHAR(100) NOT NULL, status ENUM('DRAFT','IN_PROGRESS','COMPLETED','REVIEWED','CANCELLED') NOT NULL DEFAULT 'DRAFT', overall_outcome ENUM('PASS','FAIL','OBSERVATION','NA') NULL, scheduled_at DATETIME NULL, started_at DATETIME NULL, completed_at DATETIME NULL, findings_summary TEXT NULL, corrective_action_summary TEXT NULL, follow_up_at DATETIME NULL, notes TEXT NULL, created_by_user_id BIGINT UNSIGNED NULL, updated_by_user_id BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL,
    CONSTRAINT fk_inspections_company FOREIGN KEY (company_id) REFERENCES companies(company_id) ON DELETE CASCADE, CONSTRAINT fk_inspections_site FOREIGN KEY (site_id) REFERENCES sites(site_id) ON DELETE RESTRICT, CONSTRAINT fk_inspections_employee FOREIGN KEY (inspector_employee_id) REFERENCES employees(employee_id) ON DELETE SET NULL, CONSTRAINT fk_inspections_user FOREIGN KEY (inspector_user_id) REFERENCES users(user_id) ON DELETE SET NULL, CONSTRAINT fk_inspections_created_by FOREIGN KEY (created_by_user_id) REFERENCES users(user_id) ON DELETE SET NULL, CONSTRAINT fk_inspections_updated_by FOREIGN KEY (updated_by_user_id) REFERENCES users(user_id) ON DELETE SET NULL,
    UNIQUE KEY uq_inspections_uuid (inspection_uuid), INDEX idx_inspections_company_status (company_id,status), INDEX idx_inspections_company_site (company_id,site_id), INDEX idx_inspections_company_scheduled (company_id,scheduled_at), INDEX idx_inspections_company_deleted_at (company_id,deleted_at)
);
CREATE TABLE IF NOT EXISTS inspection_items (
    inspection_item_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, company_id BIGINT UNSIGNED NOT NULL, inspection_id BIGINT UNSIGNED NOT NULL, checklist_code VARCHAR(100) NOT NULL, checklist_label VARCHAR(255) NOT NULL, item_result ENUM('PASS','FAIL','NA','OBSERVATION') NULL, finding TEXT NULL, corrective_action TEXT NULL, item_status ENUM('OPEN','IN_PROGRESS','RESOLVED','NOT_REQUIRED') NOT NULL DEFAULT 'OPEN', due_at DATETIME NULL, resolved_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT fk_inspection_items_company FOREIGN KEY (company_id) REFERENCES companies(company_id) ON DELETE CASCADE, CONSTRAINT fk_inspection_items_inspection FOREIGN KEY (inspection_id) REFERENCES inspections(inspection_id) ON DELETE RESTRICT,
    UNIQUE KEY uq_inspection_items_checklist (inspection_id,checklist_code), INDEX idx_inspection_items_company_inspection (company_id,inspection_id), INDEX idx_inspection_items_company_status (company_id,item_status), INDEX idx_inspection_items_due_at (company_id,due_at)
);